    name: TOOL_NAME,
    description: 'List events with optional pagination cursor and page size.',
    inputSchema: {
      type: 'object',
      properties: {
        cursor: { type: 'string', description: 'Opaque pagination cursor returned from a previous call.' },
        page_size: { type: 'integer', minimum: MIN_PAGE, maximum: MAX_PAGE, description: 'Number of events per page (1-3, default 2).' }
      },
      additionalProperties: false
    }
  }];
}

export async function callTool(name, args) {
  if (name !== TOOL_NAME) {
    throw new Error(`Unknown tool: ${name}`);
  }
  const input = args && typeof args === 'object' ? args : {};
  if (Array.isArray(input)) {
    throw new Error('Invalid arguments');
