    startIndex = decodeCursor(input.cursor);
  }
  let pageSize = DEFAULT_PAGE;
  if (input.page_size !== undefined) {
    if (!Number.isInteger(input.page_size) || input.page_size < MIN_PAGE || input.page_size > MAX_PAGE) {
      throw new Error('page_size must be an integer between 1 and 3');
