import events from './events.json' with {type:'json'};

const TOOL_NAME = 'events_list';
const DEFAULT_PAGE_SIZE = 2;
const MIN_PAGE_SIZE = 1;
const MAX_PAGE_SIZE = 3;

export async function listTools() {
  return [{
    name: TOOL_NAME,
    description: 'List events with optional cursor pagination.',
    inputSchema: {
      type: 'object',
      properties: {
        cursor: { type: 'string', description: 'Opaque pagination cursor returned by a previous call.' },
        page_size: { type: 'integer', minimum: MIN_PAGE_SIZE, maximum: MAX_PAGE_SIZE, description: 'Number of events per page (1-3, default 2).' }
      },
      additionalProperties: false
    }
  }];
}

function encodeCursor(index) {
  return Buffer.from(JSON.stringify({ i: index }), 'utf8').toString('base64url');
}

function decodeCursor(cursor) {
  if (typeof cursor !== 'string' || cursor.length === 0) {
    throw new Error('Invalid cursor');
  }
  let parsed;
  try {
    parsed = JSON.parse(Buffer.from(cursor, 'base64url').toString('utf8'));
  } catch {
    throw new Error('Invalid cursor');
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed) ||
      typeof parsed.i !== 'number' || !Number.isInteger(parsed.i) ||
      parsed.i < 0 || parsed.i >= events.length) {
    throw new Error('Invalid cursor');
  }
  return parsed.i;
}

export async function callTool(name, args = {}) {
  if (name !== TOOL_NAME) {
    throw new Error(`Unknown tool: ${name}`);
  }
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Arguments must be an object');
  }
  const allowed = new Set(['cursor', 'page_size']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Unknown argument: ${key}`);
    }
  }

  let page_size = DEFAULT_PAGE_SIZE;
  if ('page_size' in args && args.page_size !== undefined && args.page_size !== null) {
    const ps = args.page_size;
    if (typeof ps !== 'number' || !Number.isInteger(ps) || ps < MIN_PAGE_SIZE || ps > MAX_PAGE_SIZE) {
      throw new Error('page_size must be an integer between 1 and 3');
    }
    page_size = ps;
  }

  let start = 0;
  if ('cursor' in args && args.cursor !== undefined && args.cursor !== null) {
    if (typeof args.cursor !== 'string') {
      throw new Error('cursor must be a string');
    }
    start = decodeCursor(args.cursor);
  }

  const slice = events.slice(start, start + page_size);
  const response = { events: slice };
  if (start + page_size < events.length) {
    response.next_cursor = encodeCursor(start + page_size);
  }
  return { content: [{ type: 'text', text: JSON.stringify(response) }] };
}
